                Box("SelectedAccent", g.transform, 0, 0, 3, 94, brass);
            Label("CaseNumber", g.transform, id, 16, 12, 255, 20, 12, brass);
            Label("Title", g.transform, title, 16, 34, 260, 26, 19, paper);
            Label("Metadata", g.transform, meta, 16, 67, 260, 20, 12, muted);
