                Label("CaseCode", p, "ACTIVE CASE   /   014", 372, 103, 750, 24, 14, brass);
                Label("CaseTitle", p, "The missing courier", 372, 140, 780, 52, 36, paper);
                Label("CaseSummary", p, "A sealed dispatch never reached the station. Review the collected\nevidence and trace the courier's final route.", 372, 204, 770, 62, 18, muted);
                Box("EvidencePanel", p, 372, 296, 804, 278, panel);
                Label("EvidenceHeader", p, "EVIDENCE   /   01 OF 03", 394, 314, 740, 22, 13, brass);
                var folder = Box("FolderIcon", p, 400, 369, 130, 147, new Color(.64f, .55f, .37f));
                Box("FolderTab", folder.transform, 0, -12, 55, 12, new Color(.64f, .55f, .37f));
                Label("FolderStamp", folder.transform, "014\n\nDISPATCH", 12, 22, 110, 100, 17, ink);
                Label("EvidenceTitle", p, "Sealed dispatch", 558, 360, 585, 35, 26, paper);
                Label("EvidenceBody", p, "DOCUMENT  /  STATION OFFICE\n\nThe envelope carries a broken wax seal.\nA departure time is underlined: 21:40.", 558, 410, 590, 116, 17, paper);
                Label("PinsHeader", p, "PIN INVENTORY", 372, 612, 550, 28, 15, brass);
                Label("PinsHint", p, "Collected markers for your investigation", 372, 646, 750, 28, 15, muted);
                string[] names = {"COURIER", "STATION", "DISPATCH", "EMPTY SLOT"};
                string[] marks = {"01", "02", "03", "--"};
                for (int i = 0; i < 4; i++)
                {
                    var g = Box("PinSlot_" + i, p, 372 + i * 206, 694, 186, 120, panel);
                    Box("PinHead", g.transform, 16, 18, 36, 36, i == 3 ? new Color(.23f, .26f, .23f) : brass);
                    Label("PinNumber", g.transform, marks[i], 23, 25, 32, 28, 17, ink);
                    Label("PinName", g.transform, names[i], 16, 78, 164, 24, 13, i == 3 ? muted : paper);
                }

                Box("FooterRule", p, 24, 843, 1152, 1, brass);
                Label("Footer", p, "ARCHIVE VIEW   /   Selectable controls and live case data require gameplay integration.", 24, 862, 1130, 24, 13, muted);
                Canvas.ForceUpdateCanvases();
                string path = Out + "/CaseInventoryUI.prefab";
                PrefabUtility.SaveAsPrefabAsset(root, path);
                File.WriteAllText(Out + "/review_manifest.json", "{\"kind\":\"ui\",\"asset_paths\":[\"" + path + "\"],\"prefab_path\":\"" + Out + "/CaseInventoryUI_Review.prefab\"}");
                File.WriteAllText(Out + "/ui-authoring-validation.json", "{\"status\":\"PASS\",\"reference_width\":1200,\"reference_height\":900,\"canvas_count\":1,\"text_count\":" + root.GetComponentsInChildren<Text>(true).Length + ",\"image_count\":" + root.GetComponentsInChildren<Image>(true).Length + ",\"interactive\":false,\"original_dirty_before\":" + dirty.ToString().ToLowerInvariant() + "}");
                result.Log("Saved standalone UI with {0} text labels; no runtime handlers or dependency edits.", root.GetComponentsInChildren<Text>(true).Length);
            }
            finally
            {
                if (original.IsValid())
                    SceneManager.SetActiveScene(original);
                if (temp.IsValid())
                    EditorSceneManager.CloseScene(temp, true);
            }

            if (original.isDirty != dirty)
                throw new Exception("Original scene dirty state changed");
            result.Log("Original scene and dirty state restored.");
        }
    }
